if(!defined('WP_CLI')||!WP_CLI||DB_HOST!=='amsec-next-db'||!in_array(DB_NAME,['wordpress','wordpress69'],true)){exit(1);}
use AmazingPlugins\Security\Passkeys\{PasskeyUi,PasskeyPolicy,PasskeyTables};
$ui=new PasskeyUi($GLOBALS['wpdb']);$assert=static function($v,$m){if(!$v)throw new RuntimeException($m);};$saved=[];foreach(['siteurl',PasskeyPolicy::OPTION] as $k)$saved[$k]=get_option($k,null);$server=$_SERVER;$id=get_current_user_id();
try{
 update_option('siteurl','https://example.com',false);update_option(PasskeyPolicy::OPTION,wp_json_encode(['version'=>1,'enabled'=>true,'revision'=>bin2hex(random_bytes(16))]),false);$_SERVER['HTTPS']='on';
 ob_start();$ui->profile(get_userdata($id));$html=ob_get_clean();$assert(str_contains($html,'id="amsec-passkeys"')&&str_contains($html,'aria-live="polite"')&&str_contains($html,'autocomplete="current-password"'),'Own profile controls missing.');$assert(str_contains($html,'username and display name')&&str_contains($html,'other devices'),'Profile does not explain the name sent to the device.');$assert(str_contains($html,'The passkey is the sign-in.')&&str_contains($html,'when you sign in with a password')&&str_contains($html,'site address')&&!str_contains($html,'policies still apply')&&!str_contains($html,'ES256'),'Profile still mixes passkey sign-in with a verification code or protocol jargon.');$assert(!str_contains($html,'<form'),'Profile markup nests a form.');
 $other=new WP_User();$other->ID=$id+10000;ob_start();$ui->profile($other);$assert(ob_get_clean()==='','Another account profile exposed own controls.');
 wp_set_current_user(0);ob_start();$ui->login();$html=ob_get_clean();$assert(str_contains($html,'amsec-passkey-signin')&&str_contains($html,'type="button"')&&str_contains($html,'Sign in with a passkey')&&str_contains($html,'verification code when you sign in with your password')&&!str_contains($html,'enter it above'),'Native login control missing or still asks for a code first.');
 update_option(PasskeyPolicy::OPTION,wp_json_encode(['version'=>1,'enabled'=>false,'revision'=>bin2hex(random_bytes(16))]),false);ob_start();$ui->login();$assert(ob_get_clean()==='','Disabled policy exposes login control.');
 echo "Native own-profile scope, device name disclosure, accessible status/password controls, no nested form, passkey login copy and disabled policy passed.\n";
}finally{wp_set_current_user($id);$_SERVER=$server;foreach($saved as $k=>$v){if($v===null)delete_option($k);else update_option($k,$v,false);}}
